use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ".chars().collect::<Vec<char>>()
    for line in text.lines() {
        let parts = line.split_whitespace().map(|p| p.to_string()).collect::<Vec<string>>()
        if parts.len() < 3 {
            continue
        }
        let from = parts[1].parse::<int>().unwrap_or(10)
        let to = parts[2].parse::<int>().unwrap_or(10)
        let mut n = 0
        for c in parts[0].chars() {
            let mut d = 0
            let mut i = 0
            while i < 36 {
                if digits[i] == c {
                    d = i as int
                }
                i += 1
            }
            n = n * from + d
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out = ""
        while n > 0 {
            let r = n % to
            out = digits[r as usize].to_string() + out
            n = n / to
        }
        println("${out}")
    }
}

